# ruff: noqa: E501
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["ui"])

_HTML = r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Application Diagnosis Platform</title><style>body{font-family:system-ui;margin:auto;max-width:1000px;padding:24px;background:#f8fafc;color:#0f172a}section{background:white;padding:18px;margin:14px 0;border:1px solid #cbd5e1;border-radius:10px}input,textarea,select,button{padding:8px;margin:4px;max-width:95%}textarea{width:90%;height:70px}button{background:#2563eb;color:white;border:0;border-radius:6px}pre{white-space:pre-wrap;background:#f1f5f9;padding:12px;overflow:auto}.actions{display:flex;flex-wrap:wrap}</style></head><body><h1>应用诊断闭环 · Phase 2</h1><section><h2>创建诊断</h2><input id="title" placeholder="标题"><textarea id="symptom" placeholder="症状描述"></textarea><textarea id="log" placeholder="日志（可选）"></textarea><button onclick="createCase()">创建</button></section><section><h2>诊断操作</h2><input id="id" size="40" placeholder="Diagnosis ID"><div class="actions"><button onclick="loadAll()">查看</button><button onclick="runCase()">启动 Run</button><button onclick="trace()">查看 Trace</button><button onclick="report()">查看报告</button></div><textarea id="supplement" placeholder="补充信息"></textarea><button onclick="supplement()">补充</button><div class="actions"><button onclick="confirmAction('confirm')">确认</button><button onclick="confirmAction('reject')">驳回</button><button onclick="confirmAction('continue_investigation')">继续调查</button></div></section><section><h2>结果</h2><pre id="out">等待操作</pre></section><script>const out=document.querySelector('#out');const did=()=>document.querySelector('#id').value.trim();async function req(url,opt){const r=await fetch(url,opt);const t=await r.text();if(!r.ok)throw Error(t);try{return JSON.parse(t)}catch{return t}}function show(x){out.textContent=typeof x==='string'?x:JSON.stringify(x,null,2)}async function createCase(){try{const x=await req('/api/v1/diagnoses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.value,symptom:symptom.value,submitted_log:log.value||null})});id.value=x.id;show(x)}catch(e){show(e.message)}}async function loadAll(){try{show({diagnosis:await req('/api/v1/diagnoses/'+did()),evidence:await req('/api/v1/diagnoses/'+did()+'/evidence'),runs:await req('/api/v1/diagnoses/'+did()+'/runs')})}catch(e){show(e.message)}}async function runCase(){try{show(await req('/api/v1/diagnoses/'+did()+'/runs',{method:'POST'}))}catch(e){show(e.message)}}async function trace(){try{show(await req('/api/v1/diagnoses/'+did()+'/trace'))}catch(e){show(e.message)}}async function supplement(){try{show(await req('/api/v1/diagnoses/'+did()+'/supplements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:document.querySelector('#supplement').value,type:'user_statement'})}))}catch(e){show(e.message)}}async function confirmAction(action){try{show(await req('/api/v1/diagnoses/'+did()+'/confirmation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})}))}catch(e){show(e.message)}}async function report(){try{show(await req('/api/v1/diagnoses/'+did()+'/report.md'))}catch(e){show(e.message)}}</script></body></html>"""


@router.get("/ui", response_class=HTMLResponse)
async def ui() -> str:
    return _HTML
